fn sqlite_snapshot_semio_document_all_typed_blocks_run_option_presence_and_native_state(){let s=fixture();let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let r=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(r,s);assert_eq!(<SemioDocumentSnapshot as store::ArtifactPack>::encode_pack(&r),<SemioDocumentSnapshot as store::ArtifactPack>::encode_pack(&s));assert_eq!(<SemioDocumentSnapshot as store::ArtifactDsl>::print_dsl(&r),<SemioDocumentSnapshot as store::ArtifactDsl>::print_dsl(&s));assert_eq!(restore(&project(&SemioDocumentSnapshot::default())).unwrap(),SemioDocumentSnapshot::default());}
